{"cards": [{"node_code": "N_359263d9e504cc9b", "definition": "研究基于轮式、履带式及复合驱动结构的移动机器人，涵盖底盘机构设计、越障能力及平面运动控制。", "boundary": "聚焦于地面移动平台的机械结构、驱动方式及运动学/动力学特性。边界在于强调“地面接触”与“轮/履带驱动”，足式、飞行及水下机器人归入相应兄弟节点；纯导航算法归入“机器感知、智能控制与自主系统”。", "includes": ["差速、全向、阿克曼等轮式底盘及履带、轮履复合机构", "移动平台的运动学、动力学建模及平面运动控制", "针对复杂地形的越障机构与底盘适应性设计"], "excludes": ["双足、四足等足式机器人及飞行机器人", "水下航行器及水面无人平台"], "sibling_distinctions": [{"other_code": "N_3bec88db479d5c6e", "rule": "本节点关注轮/履带驱动的地面移动平台，兄弟节点关注足式及飞行机器人。"}, {"other_code": "N_74788b310b97cdba", "rule": "本节点关注通用地面移动底盘技术，兄弟节点关注特定环境（水下、野外、危险）下的特种应用。"}], "cross_boundary_rule": "若移动平台主要用于特定特种环境（如水下或核工业），主挂载“水下、野外与特种机器人”；若强调通用底盘结构或运动控制理论，主挂载本节点。"}, {"node_code": "N_3bec88db479d5c6e", "definition": "研究足式（双足、四足等）及飞行（旋翼、固定翼等）机器人，涵盖其机构设计、步态规划及飞行控制。", "boundary": "聚焦于非轮式/履带式的移动方式，包括足式机器人的平衡与步态，以及飞行机器人的气动布局与飞行控制。边界在于强调“足式”与“飞行”特性，地面轮式/履带归入“轮式、履带式与复合移动机器人”，水下归入“水下、野外与特种机器人”。", "includes": ["双足、四足及多足机器人的机构设计与步态规划", "旋翼、固定翼及混合飞行机器人的气动设计与飞行控制", "足式与飞行机器人的平衡控制及动态稳定性研究"], "excludes": ["轮式、履带式地面移动机器人", "水下航行器及水面无人平台"], "sibling_distinctions": [{"other_code": "N_359263d9e504cc9b", "rule": "本节点关注足式及飞行移动方式，兄弟节点关注轮式及履带式地面移动方式。"}, {"other_code": "N_74788b310b97cdba", "rule": "本节点关注足式/飞行的通用移动技术，兄弟节点关注特定环境（如水下、核工业）下的特种应用。"}], "cross_boundary_rule": "若足式/飞行机器人专门用于特定特种环境（如太空或深海），主挂载“水下、野外与特种机器人”；若强调足式/飞行的通用机构与控制理论，主挂载本节点。"}, {"node_code": "N_74788b310b97cdba", "definition": "研究适用于水下、野外、核工业、空间及医疗等特定环境的特种移动机器人，涵盖其环境适应性与专用功能。", "boundary": "聚焦于机器人在非标准或极端环境下的应用，强调环境交互、防护设计及专用任务执行。边界在于强调“特种环境”与“专用应用”，通用底盘或足式/飞行技术归入相应兄弟节点；纯感知算法归入“机器感知、智能控制与自主系统”。", "includes": ["水下机器人与水面无人平台的设计及控制", "农业、工程、救援、核工业、空间及医疗等特种环境机器人", "针对特定环境的防护、通信及任务执行系统设计"], "excludes": ["通用轮式、履带式、足式及飞行机器人的基础机构与控制理论", "固定基座的工业机械臂及末端执行器"], "sibling_distinctions": [{"other_code": "N_359263d9e504cc9b", "rule": "本节点关注特定环境下的特种应用，兄弟节点关注通用地面移动底盘技术。"}, {"other_code": "N_3bec88db479d5c6e", "rule": "本节点关注特定环境下的特种应用，兄弟节点关注足式及飞行的通用移动技术。"}], "cross_boundary_rule": "若机器人设计强调特定环境适应性（如水下耐压、核辐射防护），主挂载本节点；若强调通用移动机构（如轮式底盘、四足步态），主挂载相应通用移动机器人节点。"}]